//! Interned names: tag and attribute names, namespaces, prefixes, ids and classes.
//!
//! The types and the `local_name!`, `ns!`, `namespace_prefix!` and `atom!`
//! macros are generated by `build.rs` with `string_cache_codegen`.

// The generated code adds one `pub const` per static atom, which the macros
// expand to. They are reached through the macros, never by name.
#![allow(
    missing_docs,
    reason = "generated constants are only reached through the atom macros"
)]

include!(concat!(env!("OUT_DIR"), "/local_name.rs"));
include!(concat!(env!("OUT_DIR"), "/namespace.rs"));
include!(concat!(env!("OUT_DIR"), "/prefix.rs"));
include!(concat!(env!("OUT_DIR"), "/atom.rs"));

/// A fully qualified element or attribute name.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct QualName {
    /// The prefix as written in the source, if any.
    pub prefix: Option<Prefix>,
    /// The namespace URL.
    pub ns: Namespace,
    /// The name without its prefix.
    pub local: LocalName,
}

impl QualName {
    /// An HTML element name, such as `div`.
    pub fn html(local: LocalName) -> Self {
        Self {
            prefix: None,
            ns: ns!("http://www.w3.org/1999/xhtml"),
            local,
        }
    }

    /// An attribute name in no namespace, such as `class`: how HTML
    /// attributes are named.
    pub fn attribute(local: LocalName) -> Self {
        Self {
            prefix: None,
            ns: ns!(""),
            local,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn static_and_dynamic_atoms_compare_by_value() {
        assert_eq!(local_name!("div"), LocalName::from("div"));
        assert_eq!(&*LocalName::from("my-widget"), "my-widget");
        assert_eq!(QualName::html(local_name!("p")).local, LocalName::from("p"));
    }
}
